function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof BAMBOO_INFO&&(e.innerHTML=BAMBOO_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-val">${e.value}</div>\n            <div class="stat-lbl">${e.label}</div>\n        </div>\n    `).join(""))}function renderRegions(){const e=document.getElementById("regional-grid");e&&"undefined"!=typeof REGIONAL_CRAFTS&&(e.innerHTML=REGIONAL_CRAFTS.map(e=>`\n        <div class="regional-card">\n            <div class="regional-tag">${e.highlight}</div>\n            <h3>${e.name}</h3>\n            <p>${e.description}</p>\n        </div>\n    `).join(""))}function renderProcess(){const e=document.getElementById("process-steps");e&&"undefined"!=typeof PROCESS_STEPS&&(e.innerHTML=PROCESS_STEPS.map(e=>`\n        <div class="step-card">\n            <div class="step-num">Step ${e.step}</div>\n            <div class="step-content">\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n                ${e.image?`<img class="step-image" src="${e.image}" alt="${e.title}" loading="lazy" />`:""}\n            </div>\n        </div>\n    `).join(""))}function renderGallery(){const e=document.getElementById("gallery-grid");e&&"undefined"!=typeof GALLERY_ITEMS&&(e.innerHTML=GALLERY_ITEMS.map(e=>`\n        <div class="gallery-card">\n            <img src="${e.image}" alt="${e.title}" loading="lazy" />\n            <div class="gallery-body">\n                <h3>${e.title}</h3>\n                <p>${e.caption}</p>\n            </div>\n        </div>\n    `).join(""))}function renderSustainability(){const e=document.getElementById("sustainability-grid");e&&"undefined"!=typeof SUSTAINABILITY_POINTS&&(e.innerHTML=SUSTAINABILITY_POINTS.map(e=>`\n        <div class="sustainability-card">\n            <h3>🌱 ${e.title}</h3>\n            <p>${e.description}</p>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("references-list");e&&"undefined"!=typeof REFERENCES&&(e.innerHTML=REFERENCES.map(e=>`\n        <li>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">📚 ${e.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderRegions(),renderProcess(),renderGallery(),renderSustainability(),renderReferences(),initThemeToggle()});